"""asa/swarm/issue_client.py against a mocked GitHub API."""

import json

import pytest

from asa.swarm import issue_client as ic

SWARM_COMMENT = (
    "**DeepSeek-V4.1-Flash 763B** (ASA swarm, 16 free runners):\n\n"
    "The answer is 92.\nSecond line.\n\n---\n_Generated by the ASA Swarm workflow_\n"
)
BOT = {"login": "github-actions[bot]"}


class FakeGitHub:
    def __init__(self):
        self.calls = []
        self.comments = {}  # issue -> list
        self.status_override = None

    def __call__(self, method, url, headers, body):
        self.calls.append((method, url, headers, json.loads(body) if body else None))
        if self.status_override:
            return self.status_override, json.dumps({"message": "Bad credentials"}).encode()
        path = url.split("/repos/o/r", 1)[1]
        if method == "POST" and path == "/issues":
            return 201, json.dumps({"number": 7}).encode()
        if method == "POST" and path.endswith("/labels"):
            return 200, json.dumps([{"name": "asa-ask"}]).encode()
        if method == "GET" and "/comments" in path:
            n = int(path.split("/")[2])
            page = int(path.split("page=")[-1])
            items = self.comments.get(n, [])
            return 200, json.dumps(items[(page - 1) * 100: page * 100]).encode()
        return 404, b'{"message":"Not Found"}'


@pytest.fixture
def gh():
    return FakeGitHub()


def client(gh, **kw):
    return ic.SwarmIssueClient("o/r", "tok", api="https://api.example", transport=gh, **kw)


def test_ask_opens_issue_then_labels(gh):
    assert client(gh).ask("How many solutions does 8-queens have?") == 7
    (m1, u1, h1, b1), (m2, u2, _, b2) = gh.calls
    assert (m1, u1) == ("POST", "https://api.example/repos/o/r/issues")
    assert b1 == {"title": "[asa-ask] How many solutions does 8-queens have?",
                  "body": "How many solutions does 8-queens have?"}
    assert h1["Authorization"] == "Bearer tok"
    assert (m2, u2, b2) == ("POST", "https://api.example/repos/o/r/issues/7/labels",
                            {"labels": ["asa-ask"]})


def test_title_truncated_and_single_line():
    t = ic.make_title("word " * 50 + "\nnext")
    assert t.startswith("[asa-ask] word word") and t.endswith("…") and "\n" not in t
    assert len(t) <= len("[asa-ask] ") + ic.TITLE_MAX


def test_parse_answer():
    assert ic.parse_answer(SWARM_COMMENT) == "The answer is 92.\nSecond line."
    assert ic.parse_answer("just a human comment") is None
    assert ic.parse_answer("") is None


def test_answer_ignores_humans_and_takes_latest(gh):
    gh.comments[7] = [
        {"user": {"login": "someone"}, "body": "fake\n_Generated by the ASA Swarm workflow_"},
        {"user": BOT, "body": SWARM_COMMENT.replace("92", "91"), "html_url": "u1"},
        {"user": BOT, "body": SWARM_COMMENT, "html_url": "u2"},
    ]
    got = client(gh).answer(7)
    assert (got.issue, got.text.splitlines()[0], got.comment_url) == (7, "The answer is 92.", "u2")


def test_answer_paginates(gh):
    gh.comments[7] = [{"user": {"login": "x"}, "body": "noise"}] * 100 + [{"user": BOT, "body": SWARM_COMMENT}]
    assert client(gh).answer(7).text.startswith("The answer is 92.")
    assert sum("/comments" in c[1] for c in gh.calls) == 2


def test_wait_polls_until_answer(gh):
    sleeps = []

    def sleep(s):
        sleeps.append(s)
        if len(sleeps) == 2:
            gh.comments[7] = [{"user": BOT, "body": SWARM_COMMENT}]

    got = client(gh, sleep=sleep, clock=lambda: 0.0).ask_and_wait("q", interval=5)
    assert got.text.startswith("The answer is 92.") and sleeps == [5, 5]


def test_wait_times_out(gh):
    t = iter([0.0, 10.0, 20.0, 31.0])
    with pytest.raises(ic.SwarmTimeout):
        client(gh, sleep=lambda s: None, clock=lambda: next(t)).wait(7, timeout=30, interval=10)


def test_api_errors_and_validation(gh):
    gh.status_override = 401
    with pytest.raises(ic.SwarmError, match="401 Bad credentials"):
        client(gh).ask("q")
    with pytest.raises(ValueError):
        client(FakeGitHub()).ask("   ")
    with pytest.raises(ValueError):
        ic.SwarmIssueClient("bad", "tok")
    with pytest.raises(ValueError):
        ic.SwarmIssueClient("o/r", "")


def test_cli(monkeypatch, capsys, gh):
    monkeypatch.setenv("ASA_SWARM_REPO", "o/r")
    monkeypatch.setenv("ASA_GITHUB_TOKEN", "tok")
    monkeypatch.setenv("GITHUB_API_URL", "https://api.example")
    monkeypatch.setattr(ic, "_default_transport", gh)
    monkeypatch.setattr(ic.SwarmIssueClient.__init__, "__defaults__",
                        (None, gh, lambda s: None, lambda: 0.0))
    assert ic.main(["ask", "q"]) == 0
    assert capsys.readouterr().out.strip() == "7"
    assert ic.main(["get", "7"]) == 3
    gh.comments[7] = [{"user": BOT, "body": SWARM_COMMENT}]
    assert ic.main(["get", "7"]) == 0
    assert capsys.readouterr().out.startswith("The answer is 92.")
    monkeypatch.delenv("ASA_GITHUB_TOKEN")
    monkeypatch.delenv("GITHUB_TOKEN", raising=False)
    assert ic.main(["get", "7"]) == 1
